import { describe, expect, it } from 'vitest';
import { classifyCodeToken, tokenizeCodeLine } from '../src/components/ui/codeTokens.js';

describe('C++ code viewer tokenizer', () => {
  it('preserves every character, including whitespace', () => {
    const lines = [
      'class EVEClient {',
      '    bool setFloat(uint32_t variableId, float value) {',
      '        return send(payload, offset + 4);',
      '    }',
      '#include <cstdint>',
      '// EVEClient.h — generated by EVE Studio',
      'const char* name = "Room Monitor";',
      'crc = (crc & 0x8000) ? (crc << 1) ^ 0x1021 : crc << 1;',
    ];
    for (const line of lines) {
      expect(tokenizeCodeLine(line).join('')).toBe(line);
    }
  });

  it('keeps indentation and inter-token spaces as standalone tokens', () => {
    const tokens = tokenizeCodeLine('    return send(payload, offset + 4);');
    expect(tokens[0]).toBe('    ');
    expect(tokens).toContain(' ');
    expect(tokens.join('')).toContain('return send(');
    expect(tokens.join('')).not.toContain('returnsend');
  });

  it('classifies the C++ token families used by the generated API', () => {
    expect(classifyCodeToken('class')).toBe('keyword');
    expect(classifyCodeToken('EVEClient')).toBe('plain');
    expect(classifyCodeToken('#include')).toBe('preprocessor');
    expect(classifyCodeToken('42')).toBe('number');
    expect(classifyCodeToken('"EV"')).toBe('string');
    expect(classifyCodeToken('// draft')).toBe('comment');
    expect(classifyCodeToken('::')).toBe('operator');
    expect(classifyCodeToken('->')).toBe('operator');
    expect(classifyCodeToken('   ')).toBe('plain');
  });

  it('handles empty lines without dropping the line itself', () => {
    expect(tokenizeCodeLine('')).toEqual(['']);
  });
});
